window.quranInsights={surahs:{1:{name:"الفاتحة",theme:"أم الكتاب وخلاصة القرآن، تجمع بين التوحيد والعبادة والتوجيه إلى الصراط المستقيم.",fadl:"هي أعظم سورة في القرآن، ولا صلاة إلا بها، وهي رقية شافية بإذن الله.",action:"رددها بتدبر في كل ركعة، فأنت تطلب من الله الهداية والثبات على الطريق الصواب."},2:{name:"البقرة",theme:"إعداد الأمة لعمارة الأرض وحمل أمانة الدين، وتشمل أحكام العبادات والمعاملات والعقيدة.",fadl:"أخذها بركة وتركها حسرة، ولا تستطيعها البطلة (السحرة).",action:"احرص على قراءة آية الكرسي وآخر البقرة كل ليلة، يكفيانك ويحفظانك بإذن الله."},3:{name:"آل عمران",theme:"الدفاع عن الإسلام أمام شبهات أهل الكتاب، وتثبيت المؤمنين بعد غزوة أُحد.",fadl:"البقرة وآل عمران تأتيان يوم القيامة كأنهما غمامتان أو غيايتان تُظلان صاحبهما.",action:"في أوقات الشدة والهزيمة، تذكر أن الله يُعلمك الصبر والثبات كما علّم المؤمنين في أُحد."},4:{name:"النساء",theme:"تنظيم العلاقات الاجتماعية والأسرية وصون حقوق الضعفاء من النساء واليتامى.",fadl:"",action:"تأمل كيف أن الإسلام أعطى المرأة حقوقها كاملة قبل أن تعرف البشرية مفهوم حقوق الإنسان."},5:{name:"المائدة",theme:"تكميل منظومة التشريع الإسلامي وصون العهود والمواثيق مع الله والناس.",fadl:"",action:"حافظ على عهودك ومواثيقك مع الله أولاً، ثم مع الناس، فالوفاء بالعهد سمة المؤمنين."},6:{name:"الأنعام",theme:"إثبات التوحيد ودحض الشرك، والرد على المشركين بالحجة والبرهان العقلي.",fadl:"",action:"تأمل في الكون من حولك: النجوم والنبات والحيوان، كلها آيات تُثبت وحدانية الله."},7:{name:"الأعراف",theme:"قصص الأنبياء مع أقوامهم دروس في الصراع الأبدي بين الحق والباطل.",fadl:"",action:"من قصص الأنبياء: الثبات على الحق لا يأتي بسهولة، فاستعد للتحديات واصبر عليها."},8:{name:"الأنفال",theme:"تنظيم معركة بدر وأحكام الجهاد والغنائم، وتربية المؤمنين على الثقة بنصر الله.",fadl:"",action:"النصر لا يأتي بالعدد والعُدة فقط، بل بالإيمان والثقة بالله والاستعداد التام."},9:{name:"التوبة",theme:"تنظيم العلاقة مع المشركين والمنافقين، وتطهير الصف الإسلامي من النفاق.",fadl:"",action:"باب التوبة مفتوح دائمًا، لكن لا تؤجلها، فاليوم أحسن من الغد في العودة إلى الله."},10:{name:"يونس",theme:"تثبيت النبي ﷺ وتسليته، وبيان أن الرسالة واحدة عبر الأنبياء جميعاً.",fadl:"",action:"دعوة يونس من بطن الحوت استجيبت في لحظتها. لا تيأس من الدعاء مهما كانت ظروفك."},11:{name:"هود",theme:"قصص الأنبياء والأمم المكذبة تُبين أن سنة الله لا تتبدل في إهلاك الظالمين.",fadl:"",action:"الاستقامة هي سر النجاة، وقد قال النبي ﷺ إن سورة هود شيّبته لما فيها من أمر الاستقامة."},12:{name:"يوسف",theme:"أحسن القصص تُعلمنا الصبر الجميل، وأن الفرج يأتي بعد الشدة دائمًا.",fadl:"",action:"مهما ضاقت بك الأحوال تذكر يوسف في الجُب وفي السجن، وانتظر فرج الله بثقة."},13:{name:"الرعد",theme:"الآيات الكونية تُثبت عظمة الله وقدرته، وأن القلوب تطمئن بذكر الله.",fadl:"",action:"في أوقات القلق والتوتر، أكثر من ذكر الله، فإن القلوب لا تسكن إلا بذكره."},14:{name:"إبراهيم",theme:"دعاء إبراهيم ﷺ نموذج للإيمان الكامل والتوكل التام على الله.",fadl:"",action:"تعلّم الدعاء من إبراهيم ﷺ: ادعُ الله بخشوع وتضرع وثقة بالاستجابة."},15:{name:"الحجر",theme:"الحفاظ على القرآن ضمان إلهي، وقصة إبليس عبرة في الكِبر والعصيان.",fadl:"",action:"لا تيأس من رحمة الله مهما عظم ذنبك، فاليأس من رحمة الله أعظم من كل ذنب."},16:{name:"النحل",theme:"النعم الإلهية المبثوثة في الكون تستوجب الشكر والتوحيد.",fadl:"",action:"عُد فانظر نعم الله عليك اليوم: صحتك، طعامك، أمنك. اشكر الله بالقول والعمل."},17:{name:"الإسراء",theme:"تشريف الإنسان وتكريمه، وأحكام الأخلاق والمعاملات في المجتمع المسلم.",fadl:"",action:"تأمل وصايا الله في هذه السورة: بر الوالدين، وإيتاء ذي القربى حقه، والبُعد عن الفواحش."},18:{name:"الكهف",theme:"العصمة من أربع فتن كبرى: فتنة الدين (أصحاب الكهف)، فتنة المال (صاحب الجنتين)، فتنة العلم (موسى والخضر)، فتنة السلطة (ذو القرنين).",fadl:"من قرأها يوم الجمعة أضاء له من النور ما بين الجمعتين، ومن حفظ عشر آيات من أولها عُصم من فتنة الدجال.",action:"اجعل قراءة الكهف عادة كل جمعة، واحرص على حفظ أوائلها حمايةً من فتنة آخر الزمان."},19:{name:"مريم",theme:"قصص الأنبياء تُبين رحمة الله بعباده المخلصين وعطاءه الذي لا يُحدّ.",fadl:"",action:"تذكر نداء زكريا ﷺ وهو شيخ كبير يدعو ربه في الخفاء، فاستجاب له الله، فلا تيأس من الدعاء."},20:{name:"طه",theme:"قصة موسى ﷺ درس في الثقة بالله وتحمل المسؤولية وبيان رحمة الله.",fadl:"",action:"عندما تشعر بالعجز أمام مهمة كبيرة، تذكر دعاء موسى: رَبِّ اشْرَحْ لِي صَدْرِي."},21:{name:"الأنبياء",theme:"قصص الأنبياء نماذج للصبر والثقة بالله، وأنهم جميعاً دعوا إلى توحيد الله.",fadl:"",action:"كل نبي مرّ بابتلاء عظيم وخرج منتصراً بفضل الله. ثق أن ابتلاءك طريقٌ لعلوّ درجتك."},22:{name:"الحج",theme:"الحج شعيرة عظيمة توحّد المسلمين وتُذكّر بالبعث والحساب.",fadl:"",action:"حتى لو لم تحج بعد، تذكر أنك جزء من أمة عالمية تجتمع لله من كل فجٍّ عميق."},23:{name:"المؤمنون",theme:"صفات المؤمنين الفائزين وكيف تُصنع نفس ناجحة في الدنيا والآخرة.",fadl:"",action:"راجع صفات المؤمنين في أولها: الخشوع في الصلاة، والإعراض عن اللغو، وأداء الزكاة. أين أنت منها؟"},24:{name:"النور",theme:"تنظيم الحياة الاجتماعية وصون الأعراض والتحذير من الفاحشة والنفاق.",fadl:"",action:"نور الله في القلوب يُكسب من غضّ بصره وأطاع ربه. الطهارة طريقٌ للإنارة."},25:{name:"الفرقان",theme:"القرآن الفرقان يُفرّق بين الحق والباطل، وصفات عباد الرحمن نموذج للمسلم المثالي.",fadl:"",action:"اقرأ صفات عباد الرحمن في آخر السورة وقيّم نفسك: الهدوء، التواضع، قيام الليل، الاعتدال."},26:{name:"الشعراء",theme:"قصص الأنبياء تُثبت نبوة محمد ﷺ وأن الكذب على الأنبياء سمة أهل الباطل.",fadl:"",action:"الحق دائماً مع الأقلية في البداية، فالأنبياء كلهم بدأوا وحدهم أو مع قلة."},27:{name:"النمل",theme:"قصة سليمان وبلقيس درس في قوة الإيمان والحكمة وحسن السياسة.",fadl:"",action:"العلم والقوة حين توجّهان لخدمة الله يُعطيان نتائج مذهلة كما في قصة سليمان ﷺ."},28:{name:"القصص",theme:"قصة موسى ﷺ بالتفصيل تُعلمنا أن نصر الله يأتي من حيث لا نتوقع.",fadl:"",action:"ضُعفك وعجزك قد يكون أحياناً بداية نصر الله عليك، كما كان مع موسى الطفل الرضيع."},29:{name:"العنكبوت",theme:"الفتنة والاختبار سنة إلهية لتمييز الصادقين من الكاذبين في الإيمان.",fadl:"",action:"بيت العنكبوت مثل للبناء على غير الله: يبدو قوياً لكنه أوهن من كل شيء. ابنِ على الله."},30:{name:"الروم",theme:"الأحداث الكونية والتاريخية دليل على أن الله هو المتحكم في مجريات الأمور.",fadl:"",action:"أمريكا وروسيا والقوى الكبرى كلها في يد الله. لا تخف من أحد وتوكل على من بيده كل شيء."},31:{name:"لقمان",theme:"وصايا لقمان الحكيم لابنه خلاصة للتربية الإسلامية الصحيحة.",fadl:"",action:"اكتب وصايا لقمان وعلّمها لأبنائك: التوحيد، بر الوالدين، إقامة الصلاة، الأمر بالمعروف والصبر."},32:{name:"السجدة",theme:"إثبات الخلق والبعث وعظمة الله الذي خلق الإنسان من طين.",fadl:"",action:"كان النبي ﷺ يقرأ السجدة في فجر الجمعة. اقتدِ به واجعلها من أوراد يومك."},33:{name:"الأحزاب",theme:"النبي ﷺ أسوة حسنة، وغزوة الأحزاب درس في الثبات أمام التحديات الكبرى.",fadl:"",action:"حين يجتمع عليك الناس تذكر غزوة الأحزاب: ثبت النبي ﷺ وانتهت الأزمة، وانتصر الإيمان."},34:{name:"سبأ",theme:"قصة سبأ وداود وسليمان تُبين أن الشكر يحفظ النعم والكفر يُزيلها.",fadl:"",action:"اشكر الله على نعمك قبل أن تُسلب منك. الشكر يحفظ النعمة ويُضاعفها."},35:{name:"فاطر",theme:"الله خالق كل شيء ومُنزل كل نعمة، والعلماء الخاشون له أولى الناس بخشيته.",fadl:"",action:"كلما ازداد علمك بالله ازداد خوفك منه وحبك له. العلم النافع هو ما يُقرّبك من الله."},36:{name:"يس",theme:"إثبات البعث والنشور وعظمة الله في الكون، وقلب القرآن.",fadl:"قلب القرآن. من قرأها ابتغاء وجه الله غُفر له.",action:"اقرأها على مرضاك وعند المحتضرين، فإنها تُيسّر أمور الآخرة وتُذكّر بالرحلة إلى الله."},37:{name:"الصافات",theme:"تسبيح الملائكة وتوحيد الله، وقصة إسماعيل والفداء نموذج للطاعة الكاملة.",fadl:"",action:"إبراهيم وإسماعيل استسلما لأمر الله كاملاً، فكان الفداء والرفعة. الاستسلام لله يُعلي مقامك."},38:{name:"ص",theme:"تثبيت النبي ﷺ بقصص داود وسليمان وأيوب، وأن الصبر طريق الكمال.",fadl:"",action:"قصة أيوب ﷺ: الابتلاء لا يعني نسيان الله لك، بل قد يكون لرفع درجتك."},39:{name:"الزمر",theme:"الإخلاص لله وحده والتوبة إليه، ووصف يوم القيامة بأبلغ الصور.",fadl:"",action:"اجعل نيتك خالصة لله في كل عمل، فالعمل بلا إخلاص كالجسد بلا روح."},40:{name:"غافر",theme:"الله غافر الذنب قابل التوب وعزيز ذو انتقام، وقصة مؤمن آل فرعون نموذج للشجاعة.",fadl:"",action:"هل يمنعك الخوف من الجهر بالحق؟ تذكر مؤمن آل فرعون الذي تحدى فرعون بكلمة الحق."},41:{name:"فصلت",theme:"القرآن شفاء ورحمة وهدى، والذين يعملون بآياته يُكرمهم الله.",fadl:"",action:"عامل القرآن كشفاء لروحك وعقلك، واقرأ وتدبّر ولا تكتفِ بالتلاوة دون تأمل."},42:{name:"الشورى",theme:"الشورى منهج إسلامي أصيل، والصبر على الأذى والعفو من صفات المؤمنين.",fadl:"",action:"لا تتخذ قراراً كبيراً وحدك، بل استشر أهل الحكمة والخبرة، فالشورى بركة وحماية من الخطأ."},43:{name:"الزخرف",theme:"زخرف الدنيا وزينتها وهم، والحقيقة الوحيدة الباقية هي تقوى الله.",fadl:"",action:"لا تنخدع بمظاهر الدنيا البراقة، فكثير من المرفّهين شقاة في باطنهم، والسعادة الحقيقية في القلب."},44:{name:"الدخان",theme:"بيان مصير المكذبين وعاقبة الغافلين عن آيات الله.",fadl:"من قرأها ليلة الجمعة أصبح مغفوراً له.",action:"اجعل ليلة الجمعة ليلة مخصوصة للقرآن والدعاء والاستغفار."},45:{name:"الجاثية",theme:"آيات الله في الكون والأنفس دليل على وجوده ووحدانيته وسيحاسب عليها.",fadl:"",action:"ستجثو كل أمة يوم القيامة أمام الله، فاستعد لهذا الموقف بطاعة الله وتقواه."},46:{name:"الأحقاف",theme:"قصة عاد تُذكّر بأن القوة المادية لا تنفع أمام غضب الله، وأن البر بالوالدين فريضة.",fadl:"",action:"مهما كنت منشغلاً، خصّص وقتاً لزيارة والديك أو الاتصال بهما، فبرّهما عبادة عظيمة."},47:{name:"محمد",theme:"الجهاد في سبيل الله ونصرة الدين، وبيان صفات المنافقين الذين يُخذلون الحق.",fadl:"",action:"نصر الله يأتي لمن نصره، فانصر دين الله بعملك وأخلاقك وكلمتك."},48:{name:"الفتح",theme:"صلح الحديبية درس في أن ما يبدو هزيمة قد يكون فتحاً مبيناً في علم الله.",fadl:"",action:"ما يبدو خسارة في نظرك قد يكون فتحاً وخيراً في علم الله. ثق بحكمة الله في تدبير أمورك."},49:{name:"الحجرات",theme:"دستور الأخلاق الإسلامية في التعامل مع الله والنبي ﷺ والمجتمع المسلم.",fadl:"",action:"راجع أخلاقك مع المسلمين: هل تتجسس؟ هل تغتاب؟ هل تسخر من أحد؟ عالج كل نقص."},50:{name:"ق",theme:"التذكير بالموت والبعث وأن الله أقرب إلى الإنسان من حبل الوريد.",fadl:"",action:"الله يعلم ما يوسوس به قلبك. عش كأنك تراه، وكن مع الله في سرك قبل علنك."},51:{name:"الذاريات",theme:"قدرة الله في الكون وفي خلق الإنسان للعبادة والتفكر.",fadl:"",action:"ما خُلقنا إلا للعبادة، فاجعل كل أعمالك عبادة بالنية الصالحة لله."},52:{name:"الطور",theme:"وصف نعيم الجنة وعذاب النار، والإيمان الحق يستوجب الشكر والطمأنينة.",fadl:"",action:"تخيّل نعيم الجنة كما وصفه الله، ثم اسأل نفسك: هل أنا في الطريق الصحيح نحوها؟"},53:{name:"النجم",theme:"إثبات صدق الوحي وأن النبي ﷺ لا ينطق عن الهوى.",fadl:"",action:"ثق أن كل ما جاء به النبي ﷺ حق من عند الله، ولا تتشكك في سنة النبي."},54:{name:"القمر",theme:"اقتراب الساعة وتكذيب المكذبين، وأن القرآن يسّره الله للذكر.",fadl:"",action:"القرآن يسّره الله للحفظ والفهم. لا تعتذر بصعوبة الحفظ، بادر واطلب التيسير من الله."},55:{name:"الرحمن",theme:"عرض نعم الله على الثقلين (الإنس والجن)، ودعوتهم لاستحضار هذه النعم والشكر عليها.",fadl:"عروس القرآن.",action:"عند كل فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ قل في قلبك: لا بشيء من آلائك ربنا نكذّب، فلك الحمد."},56:{name:"الواقعة",theme:"تصوير أحوال الناس يوم القيامة في ثلاث فئات، وبيان منازلهم في الجنة أو النار.",fadl:"من قرأها كل ليلة لم تصبه فاقة أبداً.",action:"اقرأها كل ليلة قبل النوم، وتأمل في أي الفئات الثلاث تُحب أن تكون."},57:{name:"الحديد",theme:"الإنفاق في سبيل الله والزهد في الدنيا، فالدنيا متاع الغرور.",fadl:"",action:"أنفق مما رزقك الله قبل أن تندم، فالمال الذي تُنفقه في سبيل الله هو ما يبقى حقاً."},58:{name:"المجادلة",theme:"الدفاع عن حقوق المرأة والتحذير من النجوى المحرمة وصون المجالس.",fadl:"",action:"انتبه لما تتحدث به في مجالسك، فالملائكة تكتب كل كلمة، والله يسمع كل نجوى."},59:{name:"الحشر",theme:"قصة إجلاء بني النضير درس في أن الكيد يعود على أصحابه، وآخرها أسماء الله الحسنى.",fadl:"",action:"اقرأ الآيات الأخيرة من الحشر وتأمل أسماء الله: هو الله الذي لا إله إلا هو."},60:{name:"الممتحنة",theme:"الولاء للمسلمين والبراء من الكفر لا يمنع من التعامل بالعدل والإنصاف.",fadl:"",action:"يمكنك أن تكون عادلاً ومنصفاً مع غير المسلمين مع الحفاظ على هويتك الإيمانية."},61:{name:"الصف",theme:"الصف المتحد لنصرة الله كالبنيان المرصوص، والقول والعمل يجب أن يتطابقا.",fadl:"",action:"لا تقل ما لا تفعل. التناقض بين القول والعمل آفة تُضعف الفرد والأمة."},62:{name:"الجمعة",theme:"فضل يوم الجمعة وأهمية الجماعة والتجمع على طاعة الله.",fadl:"",action:"حضور صلاة الجمعة فريضة وليست خياراً. احرص عليها واجعلها يوم إعادة شحن إيمانك."},63:{name:"المنافقون",theme:"صفات المنافقين تحذير دائم من النفاق الخفي الذي يخترق القلوب.",fadl:"",action:"راجع نفسك: هل تقول غير ما تُبطن؟ هل تتحجج بالانشغال عن الطاعة؟ هذه من علامات النفاق."},64:{name:"التغابن",theme:"يوم التغابن يوم القيامة حيث يتضح الغابن والمغبون، والإيمان بالقدر أمان للقلب.",fadl:"",action:"آمن بأن ما أصابك لم يكن ليخطئك، وما أخطأك لم يكن ليصيبك. هذا سلام القلب الحقيقي."},65:{name:"الطلاق",theme:"أحكام الطلاق وضبط العلاقات الأسرية في الأزمات مع الحفاظ على كرامة الجميع.",fadl:"",action:"حين تمر علاقتك بأزمة، التزم بحدود الله، فما شُرعت الأحكام إلا لحماية الجميع."},66:{name:"التحريم",theme:"تحريم الحلال على النفس خطأ، والتوبة النصوح الكاملة فريضة بعد كل خطيئة.",fadl:"",action:"لا تُحرّم على نفسك ما أحلّه الله تشدداً، ولا تُهوّن ما حرّمه الله. التوازن هو منهج الإسلام."},67:{name:"الملك",theme:"إثبات قدرة الله المطلقة وهيمنته على الكون، والتذكير بالموت ومساءلة العقل.",fadl:"تشفع لصاحبها في القبر، وتحول بينه وبين عذاب القبر.",action:"احفظها أو اقرأها كل ليلة، فهي حارسك في قبرك يوم لا ينفع مال ولا بنون."},68:{name:"القلم",theme:"الأخلاق العظيمة للنبي ﷺ درع ضد الأذى، وعاقبة أصحاب الجنة تحذير من البخل.",fadl:"",action:"الخلق الحسن مع الناس يُحصّنك من أذاهم ويُقرّبك من الله. تخلّق بأخلاق النبي ﷺ."},69:{name:"الحاقة",theme:"وصف القيامة وأهوالها ومصير أهل الجنة والنار وصفاً مفصلاً.",fadl:"",action:"تخيّل نفسك يوم تُعطى كتابك، هل ستفرح أم ستتمنى لو لم تُنشر صحيفتك؟"},70:{name:"المعارج",theme:"الصبر الجميل على البلاء وصفة الإنسان الهلوع وكيف يتجاوزها بالتقوى.",fadl:"",action:"الإنسان بطبعه هلوع عند الشدة منوع عند الخير. التقوى والصلاة تُعالج هذه الطبيعة."},71:{name:"نوح",theme:"دعوة نوح ﷺ لقومه تسعمائة وخمسين سنة درس عظيم في الصبر والاستمرار.",fadl:"",action:"لا تيأس من دعوة أحد إلى الخير، فنوح دعا قومه عمراً كاملاً ولم يستسلم."},72:{name:"الجن",theme:"الجن أيضاً مخاطبون بالقرآن ومكلّفون بالإيمان والطاعة.",fadl:"",action:"الجن استمعوا للقرآن فآمنوا وعادوا داعين. كلمة الحق تُؤثر حتى في غير المتوقعين."},73:{name:"المزمل",theme:"قيام الليل صانع النبي ﷺ وزاد الداعية وسلاح المسلم الحقيقي.",fadl:"",action:"ولو ركعتان في الليل يُغيّران حالك. ابدأ بقليل وثابر، فقيام الليل يصنع الرجال."},74:{name:"المدثر",theme:"النبي ﷺ ينتقل من الراحة إلى الدعوة، فالتكليف لا يعرف الراحة.",fadl:"",action:"قم من راحتك واعمل لدينك ومجتمعك ولا تؤجل الخير، فكل يوم تأخير خسارة."},75:{name:"القيامة",theme:"وصف لحظة الموت وأهوال القيامة والنفس اللوّامة التي تُحاسب صاحبها.",fadl:"",action:"نفسك اللوامة نعمة، حين تُحسّ بالذنب فهذا دليل حياة القلب. تب فوراً ولا تُهمل هذا الشعور."},76:{name:"الإنسان",theme:"نعيم الجنة جزاء الصابرين على الأذى والمنفقين في حب الله.",fadl:"",action:"الأبرار الذين يُطعمون الطعام رغم حاجتهم قائلين إنما نطعمكم لوجه الله. كن من هؤلاء."},77:{name:"المرسلات",theme:"تكرار ويل يومئذ للمكذبين عشر مرات تحذيراً وإنذاراً.",fadl:"",action:"إذا كذّبت بآيات الله فأنت في خطر. راجع عقيدتك وتثبّت من إيمانك."},78:{name:"النبأ",theme:"إثبات يوم القيامة ووصف أهواله، والرد على المشككين في البعث.",fadl:"",action:"تصوّر يوم القيامة وهوله، ثم اسأل نفسك: ماذا أعددت لهذا اليوم؟"},79:{name:"النازعات",theme:"الملائكة وأهوال القيامة وقصة موسى وفرعون درس في عاقبة الطغيان.",fadl:"",action:"فرعون قال أنا ربكم الأعلى فأخذه الله. الكِبر والغرور نهايتهما الهلاك."},80:{name:"عبس",theme:"تعليم النبي ﷺ مبدأ المساواة في الدعوة وأن كل نفس بشرية لها قيمتها عند الله.",fadl:"",action:"لا تحتقر أحداً لضعفه أو فقره، فرب إنسان بسيط هو أحب إلى الله من أهل الجاه والمناصب."},81:{name:"التكوير",theme:"أهوال يوم القيامة تُصوّر انهيار الكون وبدء الحياة الأبدية.",fadl:"",action:"تصوّر الكون يُطوى كطيّ السجل. ماذا أعددت لهذا اليوم؟"},82:{name:"الانفطار",theme:"السماء تنفطر والبحار تُفجَّر في يوم الحساب، وكل نفس ستعلم ما قدّمت.",fadl:"",action:"ما قدّمته اليوم هو ما ستجده غداً. لا تفرّط في يوم واحد من أعمارنا."},83:{name:"المطففين",theme:"التحذير من الغش والتطفيف في المعاملات، وجزاء المكذبين.",fadl:"",action:"كن أمانة في كل معاملاتك: في البيع والشراء والعمل. الغش حرام ويُذهب البركة."},84:{name:"الانشقاق",theme:"مراحل الإنسان من الدنيا إلى القيامة كلها تدلّ على عظمة الله ووجوب السجود له.",fadl:"",action:"حياتك كلها مسير نحو الله، فاجعل كل خطوة تُقرّبك منه لا تُبعدك."},85:{name:"البروج",theme:"قصة أصحاب الأخدود درس في أن الشهادة في سبيل الله أعلى مراتب الإيمان.",fadl:"",action:"هل تستطيع الثبات على دينك حين يُكلّفك ذلك التضحية؟ تدرّب على الثبات في الصغائر أولاً."},86:{name:"الطارق",theme:"الله الحافظ لكل نفس ينظر فيما تعمل، فلا يخفى عليه شيء.",fadl:"",action:"على كل نفس حافظ. سلوكك في الخلوة كسلوكك أمام الناس، فالله يراك في كل حال."},87:{name:"الأعلى",theme:"تنزيه الله وتقديسه، والقرآن ميسّر للذكر لمن أراد الله له الخير.",fadl:"كان النبي ﷺ يقرأها في صلاة الجمعة والعيد.",action:"سبّح اسم ربك الأعلى وقلها في ركوعك وسجودك بخشوع حقيقي."},88:{name:"الغاشية",theme:"يوم القيامة يغشى فيه الناس بالهول، وفريقان متباينان في المصير.",fadl:"",action:"في أي الفريقين ستكون؟ القرار الآن في يدك، غداً ستُحشر مع من أحببت وعملت لأجله."},89:{name:"الفجر",theme:"القسم بمواقيت مقدسة تُذكّر بعظمة الله، وقصة عاد وثمود وفرعون دروس في الطغيان.",fadl:"",action:"النفس المطمئنة هي الجائزة العظمى. اسعَ لاطمئنان نفسك بالتقوى لا بزخارف الدنيا."},90:{name:"البلد",theme:"الإنسان في كبد ومشقة لكنه لم يسلك العقبة: العتق، والإطعام، والإيمان.",fadl:"",action:"هل تجاوزت عقبات الأنانية اليوم؟ أطعم جائعاً أو أعتق عُنقاً أو عاون محتاجاً."},91:{name:"الشمس",theme:"القسم بمخلوقات الله يُعظّم من خلقها، وفلاح من زكّى نفسه وخاب من دسّاها.",fadl:"",action:"تزكية النفس رحلة يومية. حاسب نفسك كل ليلة: هل زكّيتها اليوم أم دسّيتها؟"},92:{name:"الليل",theme:"الناس في ساعي الجنة وساعي النار، والجزاء والمجازاة من الله العليم.",fadl:"",action:"ما أنفقته في سبيل الله لن يُنقصك شيئاً، بل سييسّر الله عليك الطريق اليسرى."},93:{name:"الضحى",theme:"تسلية الله لنبيه ﷺ وتذكيره بنعمه عليه، وحق الضعفاء والسائلين.",fadl:"",action:"في لحظات تأخر الفرج تذكر أن الله ما ودّعك ولا تركك. أمّا بنعمة ربك فحدّث."},94:{name:"الشرح",theme:"الشرح والتيسير والرفعة ثلاث عطايا ربانية للنبي ﷺ تُبشّر المؤمنين.",fadl:"",action:"مع كل عسر يُسران. استبشر في أشد اللحظات ضيقاً، فالفرج قادم بأمر الله."},95:{name:"التين",theme:"الإنسان أُبدع خلقه ليكون في أحسن تقويم، فلا يصحّ أن يسفل إلى أسفل سافلين.",fadl:"",action:"أنت مخلوق في أحسن تقويم. احفظ هذه الكرامة بالإيمان والعمل الصالح."},96:{name:"العلق",theme:"أول ما نزل من القرآن يأمر بالقراءة والعلم، فالعلم أصل الحضارة الإسلامية.",fadl:"",action:"اقرأ باسم ربك. العلم الذي يُقرّبك من الله هو أفضل استثمار لعقلك ووقتك."},97:{name:"القدر",theme:"ليلة القدر أفضل من ألف شهر، وهي فرصة مكفولة للمؤمنين كل رمضان.",fadl:"العبادة فيها خير من عبادة ألف شهر.",action:"لا تُفوّت ليالي رمضان الأخيرة، وخاصة الوتر منها، فلعلك تُصادف ليلة القدر."},98:{name:"البينة",theme:"الإسلام الدين الخالص القائم على التوحيد والصلاة والزكاة، وهو خير البرية.",fadl:"",action:"أنت من خير البرية إن أقمت الصلاة وآتيت الزكاة وآمنت بالله حق الإيمان."},99:{name:"الزلزلة",theme:"يوم القيامة تُحدّث الأرض بأخبارها عمّا عمل الناس على ظهرها.",fadl:"",action:"من يعمل مثقال ذرة خيراً يره. لا تستهن بصغائر الأعمال الصالحة فهي قد تكون نجاتك."},100:{name:"العاديات",theme:"كفران الإنسان بنعمة ربه رغم دلالة كل شيء على ضرورة شكر الله.",fadl:"",action:"إنسان كنود: ينسى المعروف ويشغله ماله. كن عكسه: اذكر نعم الله وأنفق مما أعطاك."},101:{name:"القارعة",theme:"يوم القيامة يقرع القلوب بهوله، والميزان هو الفاصل في مصير الناس.",fadl:"",action:"ثقّل ميزانك بالأعمال الصالحة، فقد تكون ذرة خير هي ما ترجح بها كفة حسناتك."},102:{name:"التكاثر",theme:"التكاثر في المال والجاه والأولاد يُلهي الإنسان عن الآخرة حتى يزوره القبر.",fadl:"",action:"كم يوماً أمضيته في تكديس ما لن تأخذه معك؟ اليوم الحقيقي هو ما عمّرته لآخرتك."},103:{name:"العصر",theme:"كل إنسان في خسارة إلا من جمع الإيمان والعمل الصالح والتواصي بالحق والصبر.",fadl:"كان الصحابة لا يفترقون حتى يتلوها.",action:"أنهِ كل لقاء بتلاوتها تذكيراً لنفسك وصاحبك بشروط الفلاح الأربعة."},104:{name:"الهمزة",theme:"الويل لكل همّاز لمّاز يحتقر الناس ويحسب أن ماله يُخلّده.",fadl:"",action:"تفقّد لسانك: هل تغتاب؟ هل تسخر؟ هل تكشف عيوب الناس؟ اللسان مفتاح النجاة أو الهلاك."},105:{name:"الفيل",theme:"قصة أصحاب الفيل دليل على أن الله يحمي بيته وأهله ويُهلك من تجرأ عليهم.",fadl:"",action:"الله حامي الحرمات وناصر المؤمنين. ثق أن الله لن يترك من آذى المسلمين دون جزاء."},106:{name:"قريش",theme:"نعمة الأمن والأكل على قريش توجب عبادة ربهم الذي أطعمهم من جوع وآمنهم من خوف.",fadl:"",action:"أنت اليوم تنعم بالأمن والطعام. هذه نعمتان عظيمتان فاشكر الله عليهما باستمرار."},107:{name:"الماعون",theme:"الصلاة الخاشعة والإنفاق على المحتاجين شرطان لصحة الدين.",fadl:"",action:"صلاة بلا خشوع ولا إنفاق نفاق. أصلح صلاتك وافتح يدك للمحتاجين."},108:{name:"الكوثر",theme:"الكوثر عطاء الله الذي لا يحصيه أحد للنبي ﷺ وللمؤمنين.",fadl:"",action:"مبغض النبي ﷺ هو الأبتر. أحبب النبي ﷺ واتبعه واطلب شفاعته."},109:{name:"الكافرون",theme:"البراءة التامة من الشرك والتوحيد الكامل لله هي العقيدة الإسلامية.",fadl:"تعدل ربع القرآن، واقرأها قبل النوم كأنك ختمت ربع القرآن.",action:"اقرأها صباحاً براءةً من الشرك، واقرأها قبل النوم وكأنك تُعلن توحيدك لله قبل أن تنام."},110:{name:"النصر",theme:"الفتح العظيم يستوجب التسبيح والاستغفار لا الغرور والتعالي.",fadl:"",action:"حين تنجح أو تفوز أو تحقق إنجازاً، قل: سبحانك اللهم وبحمدك. النجاح بفضل الله لا بقدرتك."},111:{name:"المسد",theme:"أبو لهب وامرأته نموذج للعداء الكامل للإسلام، وعاقبتهما التبّ والهلاك.",fadl:"",action:"من عادى الله ورسوله لن ينفعه مال ولا ولد. التمسك بالحق خير من التودد للمبطلين."},112:{name:"الإخلاص",theme:"خلاصة توحيد الله في أبلغ صورة وأوجزها.",fadl:"تعدل ثلث القرآن.",action:"اقرأها ثلاثاً صباحاً ومساءً، فكأنك ختمت القرآن ثلاث مرات، وجدّد توحيدك لله بها."},113:{name:"الفلق",theme:"الالتجاء إلى الله من شرور الخلق الظاهرة والخفية.",fadl:"من المُعوّذتين اللتين لا يستعاذ بمثلهما.",action:"اقرأهما (الفلق والناس) ثلاثاً صباحاً ومساءً وقبل النوم، يكفيانك كل شيء."},114:{name:"الناس",theme:"الالتجاء إلى الله من شر الوساوس الداخلية والشيطان الرجيم.",fadl:"من المُعوّذتين اللتين لا يستعاذ بمثلهما.",action:"عندما تشعر بوسواس أو أفكار سيئة، تعوّذ بالله فوراً، فالشيطان يفرّ من ذكر الله."}},verses:{"1_1":{title:"بسم الله الرحمن الرحيم",sabab:"",fadl:"كل أمر ذي بال لا يُبدأ فيه ببسم الله فهو أبتر. ابدأ بها كل عمل تجعله مباركاً.",action:"اجعل 'بسم الله' شعارك في كل شيء: الطعام، الخروج، العمل، النوم، وكل لحظة في يومك."},"1_5":{title:"إياك نعبد وإياك نستعين",sabab:"",fadl:"هذه الآية قسمٌ بين الله وعبده؛ نصفها لله (إياك نعبد) ونصفها للعبد (إياك نستعين).",action:"قبل كل صلاة تذكر: أنت تُجدد عهدك مع الله بأن لا تعبد إلا إياه ولا تطلب العون إلا منه."},"2_186":{title:"وإذا سألك عبادي عني فإني قريب",sabab:"سأل أعرابي النبي ﷺ: أقريب ربنا فنناجيه، أم بعيد فنناديه؟ فسكت النبي ﷺ، فنزل الوحي بهذه الآية العظيمة.",fadl:"",action:"الله لا يحتاج إلى واسطة ولا مواعيد ليسمعك. ارفع يدك الآن وبث إليه همومك، فهو أقرب إليك من أي شخص آخر."},"2_255":{title:"آية الكرسي - أعظم آية في القرآن",sabab:"",fadl:"من قرأها دبر كل صلاة مكتوبة لم يمنعه من دخول الجنة إلا أن يموت. ومن قرأها حين يأخذ مضجعه حفظه الله ولم يقربه شيطان حتى يصبح.",action:"حصّن بها نفسك وبيتك، واجعلها وردك الثابت بعد كل صلاة وقبل النوم. علّمها لأطفالك فهي أقوى حصن."},"2_256":{title:"لا إكراه في الدين",sabab:"نزلت في رجل من الأنصار أسلم ابناه قبله على دين آخر، فأراد إكراههما على الإسلام، فنهاه الله.",fadl:"",action:"الإسلام دين الاقتناع لا الإكراه. ادعُ بالحكمة والموعظة الحسنة، واترك الهداية لله."},"2_285":{title:"آمن الرسول - خاتمة سورة البقرة",sabab:"",fadl:"من قرأ الآيتين الأخيرتين من البقرة في ليلة كفتاه.",action:"لا تنم قبل أن تقرأ آخر آيتين من البقرة، فهما كنز عظيم تبدأ به يومك وتختم ليلتك."},"2_286":{title:"لا يكلف الله نفساً إلا وسعها",sabab:"",fadl:"هذه الآية بشارة رحمة، روى مسلم أن الله قال: نعم، حين سألت الملائكة الله أن يجيب عباده بذلك.",action:"عندما تشعر أن الأمر فوق طاقتك، تذكر أن الله لن يُكلّفك ما لا تطيق. أدِّ ما تستطيع وتوكل على الله."},"3_1":{title:"وفد نصارى نجران",sabab:"نزلت صدر هذه السورة (أول 80 آية) في وفد نصارى نجران حين قدموا على النبي ﷺ يجادلونه في عيسى عليه السلام، فبينت لهم التوحيد الخالص.",fadl:"البقرة وآل عمران تأتيان يوم القيامة كأنهما غمامتان تظلان صاحبهما.",action:"الثبات على العقيدة يبدأ بالعلم. تسلح بفهم دينك لترد على أي شبهة بحكمة وثقة كما علمنا القرآن."},"3_26":{title:"قل اللهم مالك الملك",sabab:"",fadl:"دعاء جامع يُذكّر بأن الملك كله لله وحده، يُفيد كثيراً عند الشعور بالضعف أو الخوف من أحد.",action:"حين تخشى قوياً أو تطلب رزقاً، رددها وتذكر أن مقاليد كل شيء بيد الله وحده."},"3_134":{title:"والكاظمين الغيظ والعافين عن الناس",sabab:"نزلت في الحث على مكارم الأخلاق، وقد شُتم أحد الصالحين فكظم غيظه، ثم عفا، ثم أعتق العبد الذي أغضبه تطبيقاً للآية.",fadl:"من كظم غيظاً وهو قادر على أن ينفذه، دعاه الله ليخيره من الحور العين.",action:"تذكر هذه الآية عند أول موقف يغضبك اليوم. اكتم غضبك، وتجاوز عن المخطئ، فما عند الله خير وأبقى."},"3_173":{title:"حسبنا الله ونعم الوكيل",sabab:"قالها النبي ﷺ وأصحابه حين خوّفهم الناس وقالوا: إن الناس قد جمعوا لكم، فما زادهم ذلك إلا إيماناً.",fadl:"كلمة إبراهيم ﷺ حين ألقي في النار، وكلمة النبي ﷺ حين أُخبر بتجمع الأعداء.",action:"في أوقات الضيق والخوف رددها بيقين وتوكل حقيقي، فإن الله كافٍ من توكل عليه."},"4_36":{title:"وبالوالدين إحساناً",sabab:"",fadl:"",action:"رضا الله مقرون برضا الوالدين. اتصل بأحد والديك الآن، أو ادعُ لهما بالرحمة إن كانا قد توفيا."},"8_1":{title:"يسألونك عن الأنفال",sabab:"نزلت في غزوة بدر حين اختلف الصحابة في توزيع الغنائم، فأنزل الله السورة ليُبين أن مردها لله ورسوله، تهذيباً للنفوس.",fadl:"",action:"لا تجعل الدنيا ومكاسبها سبباً للخلاف مع إخوانك. تقوى الله وإصلاح ذات البين أعظم من كل الغنائم."},"8_33":{title:"أمان أهل الأرض (الاستغفار)",sabab:"قال المشركون: اللهم إن كان هذا هو الحق فأمطر علينا حجارة، فأنزل الله أنه لن يعذبهم والنبي فيهم، ولن يعذبهم وهم يستغفرون.",fadl:"قال ابن عباس: كان فيكم أمانان: نبي الله والاستغفار، فذهب النبي ﷺ وبقي الاستغفار.",action:"اجعل الاستغفار وردك الدائم، فهو أمانك من العذاب، ومفتاحك للرزق وتفريج الكروب."},"9_1":{title:"براءة من المشركين",sabab:"نزلت لنقض العهود مع المشركين الذين خانوا عهودهم مع المسلمين مراراً، ولذلك لم تبدأ بالبسملة لأنها نزلت بالسيف والوعيد.",fadl:"",action:"المؤمن يفي بعهده ويتسامح، ولكنه لا يقبل الذل والمهانة والخيانة. كن حازماً مع من يستغل طيبتك."},"9_40":{title:"لا تحزن إن الله معنا",sabab:"قالها النبي ﷺ لأبي بكر الصديق ﵁ وهما مختبئان في غار ثور، والمشركون يقفون على باب الغار، فأنزل الله سكينته عليهما.",fadl:"",action:"حين تظن أن كل الأبواب مغلقة، وأن المشاكل تحاصرك من كل اتجاه، ردد بيقين: لا تحزن إن الله معنا."},"9_51":{title:"قل لن يصيبنا إلا ما كتب الله لنا",sabab:"",fadl:"",action:"الإيمان بالقدر يُعطيك سكينة لا مثيل لها. ما أصابك لم يكن ليخطئك، وما أخطأك لم يكن ليصيبك."},"12_87":{title:"لا تيأس من روح الله",sabab:"قالها يعقوب ﷺ لأبنائه وهو يبعثهم يبحثون عن يوسف بعد سنوات طويلة من الفراق والألم.",fadl:"",action:"مهما طال انتظارك وعظم همّك، تذكر يعقوب ﷺ الذي صبر سنين وما يئس، ففرّج الله عنه."},"13_28":{title:"ألا بذكر الله تطمئن القلوب",sabab:"",fadl:"هذه الآية وصفة ربانية للقلق والاضطراب النفسي لا تعوضها أي دواء.",action:"عندما تشعر بالقلق أو الاضطراب، أكثر من ذكر الله، فهو الدواء الوحيد لاطمئنان القلب حقاً."},"14_7":{title:"لئن شكرتم لأزيدنكم",sabab:"",fadl:"وعد إلهي مطلق بالزيادة مقابل الشكر، لم يُقيّده الله بوقت أو مكان.",action:"اكتب اليوم ثلاث نعم شكرت الله عليها، وجرّب هذا العمل كل يوم وانظر كيف تتغير حياتك."},"17_23":{title:"وقضى ربك ألا تعبدوا إلا إياه",sabab:"",fadl:"وضع الله الأمر ببرّ الوالدين مباشرة بعد الأمر بعبادته وحده، دلالة على عظم مكانتهما.",action:"اليوم ابتسم في وجه والديك، قبّل رأسيهما، واسمع كلامهما بصبر. هذا عبادة لله قبل أن يكون طاعة لهما."},"18_10":{title:"آية أصحاب الكهف",sabab:"نزلت حين سأل المشركون النبي ﷺ عن الفتية الذين آمنوا وفرّوا بدينهم من ملك ظالم.",fadl:"",action:"الثبات على الدين قد يكلفك التضحية بالراحة أو الجاه. الفتية اختاروا الكهف على الراحة الزائفة."},"18_23":{title:"ولا تقولن لشيء إني فاعل ذلك غدا",sabab:"سأل المشركون النبي ﷺ عن الروح وأصحاب الكهف، فقال: غداً أجيبكم، ولم يقل (إن شاء الله)، فانقطع عنه الوحي 15 يوماً عتاباً له.",fadl:"",action:"لا تضمن الغد، ولا تقطع وعداً إلا وقرنته بمشيئة الله (إن شاء الله). فكل خططنا مرهونة بإرادته سبحانه."},"20_25":{title:"رب اشرح لي صدري",sabab:"قالها موسى ﷺ حين أرسله الله لمواجهة فرعون، وهو يشعر بثقل المهمة.",fadl:"",action:"قبل كل مهمة صعبة أو كلمة مهمة، قل: رب اشرح لي صدري ويسر لي أمري، فالله يستجيب."},"21_83":{title:"دعاء أيوب في الضر",sabab:"قالها أيوب ﷺ بعد سنوات طويلة من المرض والابتلاء الشديد.",fadl:"استجاب الله لأيوب ﷺ وكشف ضره، وهذا الدعاء مستجاب لمن قاله بصدق.",action:"في أشد لحظات الألم والمرض قل: رَبِّ إِنِّي مَسَّنِيَ الضُّرُّ وَأَنتَ أَرْحَمُ الرَّاحِمِينَ وتوقع الفرج."},"21_87":{title:"تسبيح يونس في بطن الحوت",sabab:"قالها يونس ﷺ وهو في بطن الحوت في ظلمات ثلاث.",fadl:"ما دعا بها مكروب إلا استجاب الله له.",action:"في أضيق لحظاتك ردد: لا إله إلا أنت سبحانك إني كنت من الظالمين، فهي مفتاح الفرج."},"24_11":{title:"إن الذين جاءوا بالإفك عصبة منكم",sabab:"نزلت لتبرئة أم المؤمنين عائشة رضي الله عنها بعد أن اتهمها المنافقون في عِرضها وظلت تبكي شهراً كاملاً حتى نزل الوحي.",fadl:"",action:"لا تنقل شائعة، ولا تساهم في نشر كلام يمس أعراض الناس. قف عند حدود الله وقل: سبحانك هذا بهتان عظيم."},"24_22":{title:"دعوة للعفو والصفح",sabab:"نزلت في أبي بكر الصديق ﵁ حين حلف ألا ينفق على مسطح بن أثاثة بعد مشاركته في حادثة الإفك، فدعاه الله للعفو.",fadl:"",action:"هل تحب أن يغفر الله لك؟ إذن اغفر للناس زلاتهم واعفُ عمن أخطأ في حقك، فالجزاء من جنس العمل."},"27_62":{title:"أمن يجيب المضطر إذا دعاه",sabab:"",fadl:"الله يستجيب لدعاء المضطر بلا استثناء، أياً كان هذا المضطر.",action:"اشعر باضطرارك لله في كل دعاء، فكلما كان قلبك أكثر حاجة وانكساراً، كانت الاستجابة أقرب."},"28_24":{title:"رب إني لما أنزلت إلي من خير فقير",sabab:"قالها موسى ﷺ بعد أن هرب من فرعون خائفاً، وسقى للفتاتين ماءهما، وجلس في الظل وحيداً جائعاً لا مأوى له.",fadl:"دعاء عظيم لجلب الرزق والزوج الصالح والمأوى.",action:"إذا انقطعت بك الأسباب وشعرت بالوحدة والحاجة، ردد دعاء موسى، فبه رُزق الأمن والعمل في أيام معدودة."},"30_1":{title:"الم غلبت الروم",sabab:"حزن المسلمون لانتصار الفرس (عبدة النار) على الروم (أهل الكتاب)، فنزلت السورة تبشر بانتصار الروم خلال بضع سنين، وتحققت النبوءة العظيمة.",fadl:"",action:"مهما طالت جولات الباطل، فإن العاقبة للحق. لا تفقد الأمل في نصر الله وفي إجابة دعائك حتى في أحلك الظروف."},"39_53":{title:"يا عبادي الذين أسرفوا على أنفسهم",sabab:"",fadl:"هذه الآية سيدة آيات الرجاء في القرآن، نزلت رحمةً بأهل الذنوب والمسرفين على أنفسهم.",action:"مهما عظم ذنبك لا تيأس من رحمة الله، فإن الله يغفر الذنوب جميعاً لمن تاب وأناب."},"40_60":{title:"ادعوني أستجب لكم",sabab:"",fadl:"وعد إلهي مطلق بالاستجابة، وتركُ الدعاء استكباراً يستوجب دخول جهنم.",action:"لا تتأخر في الدعاء ولا تعجل في طلب الاستجابة. اللهم إنك سميع مجيب، أدعوك ثقةً بك لا شكاً."},"48_1":{title:"إنا فتحنا لك فتحاً مبيناً",sabab:"نزلت على النبي ﷺ في طريق عودته من صلح الحديبية، وكان الصحابة في حزن لعدم دخول مكة، فبشرهم الله بأنه فتح عظيم.",fadl:"قال عنها النبي ﷺ: «لقد أُنزلت علي الليلة سورةٌ، لَهي أحبُّ إليَّ مما طلعت عليه الشمس».",action:"ما تراه اليوم حرماناً أو تأخيراً في إجابة دعائك، قد يكون هو الفتح الحقيقي لك في علم الله. ثق بتدبيره."},"49_1":{title:"لا تقدموا بين يدي الله ورسوله",sabab:"ارتفع صوت أبي بكر وعمر رضي الله عنهما بحضرة النبي ﷺ في خلاف حول تعيين أمير، فنزلت السورة تؤدب الصحابة في كيفية التعامل مع النبي ﷺ والأدب معه.",fadl:"",action:"الأدب مع الله ورسوله يقتضي عدم تقديم رأيك أو هواك على النص القرآني والنبوي. استسلم لأمر الله يأتيك الخير."},"49_11":{title:"لا يسخر قوم من قوم",sabab:"نزلت في مجموعة من الصحابة سخروا من بلال وصهيب وعمار لفقرهم، وفي بعض النساء سخرن من أم سلمة لِقصرها، فنهاهم الله.",fadl:"",action:"احذر من التنمر والسخرية ولو بالمزاح. ربما يكون من تسخر منه أنقى قلباً وأحب إلى الله منك."},"55_1":{title:"الرحمن - أول آية في عروس القرآن",sabab:"",fadl:"الرحمن أحد أسماء الله الحسنى، يُذكّر بأن كل نعمة تصلك هي من رحمته وحده.",action:"ابدأ يومك بتذكر اسم الرحمن، وقل: يا رحمن ارحمني برحمتك التي وسعت كل شيء."},"58_1":{title:"قد سمع الله قول التي تجادلك في زوجها",sabab:"نزلت في خولة بنت ثعلبة التي ظاهر منها زوجها، فجاءت تشتكي للنبي ﷺ وتبكي، فسمع الله شكواها من فوق سبع سماوات.",fadl:"",action:"مهما كان صوتك خافتاً وشكواك حبيسة صدرك، فإن الله يسمعك كما سمع خولة. بث شكواك لمن بيده الحل."},"59_1":{title:"جلاء بني النضير",sabab:"نزلت في يهود بني النضير حين نقضوا عهدهم وحاولوا اغتيال النبي ﷺ، فحاصرهم المسلمون وأجلوهم عن المدينة بغير قتال شديد.",fadl:"",action:"(فاعتبروا يا أولي الأبصار).. لا تغتر بقوتك ومالك وحصونك، فإذا أراد الله أمراً أتاك من حيث لم تحتسب."},"59_9":{title:"ويؤثرون على أنفسهم ولو كان بهم خصاصة",sabab:"نزلت في أبي طلحة الأنصاري وزوجته، اللذين أطفآ السراج ووضعا طعامهما القليل لضيف رسول الله ﷺ وباتا جائعين.",fadl:"قال لهم النبي ﷺ: لقد عجب الله من صنيعكما بضيفكما الليلة.",action:"الإيثار من أعلى مراتب الكرم. جرّب اليوم أن تُعطي شيئاً تحبه لمحتاج، وراقب البركة التي ستحل بقلبك."},"60_1":{title:"قصة حاطب بن أبي بلتعة",sabab:"أرسل الصحابي حاطب رسالة سرية لقريش يخبرهم بتجهيز النبي ﷺ لفتح مكة (حماية لأهله هناك)، فنزل الوحي يعاتبه، وعفا عنه النبي ﷺ لحضوره بدراً.",fadl:"",action:"الولاء التام لله وللمؤمنين فوق كل اعتبار. لا تجعل الخوف على العائلة أو المال يبرر لك الوقوف مع الباطل."},"63_1":{title:"إذا جاءك المنافقون",sabab:"نزلت تفضح رأس المنافقين عبد الله بن أبي بن سلول الذي حلف كذباً أنه لم يقل «لئن رجعنا إلى المدينة ليخرجن الأعز منها الأذل»، ففضحه الله.",fadl:"",action:"احذر من النفاق القولي والعملي. كن صادقاً مع الله من الداخل كما تظهر للناس من الخارج."},"63_9":{title:"يا أيها الذين آمنوا لا تلهكم أموالكم",sabab:"تحذير من الله للمؤمنين ألا تشغلهم الدنيا (المال والأولاد) عن الصلاة والطاعة كما شغلت المنافقين.",fadl:"",action:"المال والأولاد زينة ونعمة، فلا تجعلها سبباً في غفلتك عن صلاتك وقرآنك لكي لا تكون من الخاسرين."},"65_2":{title:"ومن يتق الله يجعل له مخرجا",sabab:"نزلت في عوف بن مالك الأشجعي حين أُسر ابنه واشتد فقره، فأمره النبي بكثرة (لا حول ولا قوة إلا بالله)، ففك الله أسر ابنه ورجع بغنائم.",fadl:"",action:"مفتاح كل مشكلة مغلقة هو (التقوى). اترك الذنوب، والتزم بأمر الله، وسيرزقك من باب لا تتخيله أبداً."},"65_3":{title:"ومن يتوكل على الله فهو حسبه",sabab:"",fadl:"وعد ربّاني بأن الله كافٍ لمن توكل عليه حق التوكل مع الأخذ بالأسباب.",action:"خُذ بالأسباب كاملاً، ثم أسلم أمرك لله، فالتوكل لا يعني الكسل بل يعني الثقة بعد العمل."},"66_1":{title:"يا أيها النبي لم تحرم ما أحل الله لك",sabab:"امتنع النبي ﷺ عن شرب العسل إرضاءً لبعض زوجاته بعد أن تظاهرن بأن رائحته سيئة، فعاتبه الله بألا يحرم حلالاً إرضاءً لأحد.",fadl:"",action:"لا تترك حقاً أو حلالاً أو متعة مباحة إرضاءً للناس على حساب نفسك. التوازن والعدل مطلب شرعي."},"67_2":{title:"الذي خلق الموت والحياة ليبلوكم",sabab:"",fadl:"",action:"الحياة كلها اختبار، والابتلاء للتمييز لا للتعذيب. اسأل نفسك في كل موقف: هل أحسنت العمل؟"},"74_1":{title:"يا أيها المدثر قم فأنذر",sabab:"عاد النبي ﷺ من غار حراء يرتجف من رؤية جبريل وقال لزوجته خديجة: دثروني دثروني، فناداه الله ليقوم ويبدأ رحلة الدعوة الطويلة.",fadl:"",action:"الراحة انتهت حين بدأ التكليف. انهض من سريرك وغطاء كسلك، واعمل لدنياك وآخرتك بحماس ونشاط."},"80_1":{title:"عتاب رقيق من رب العالمين",sabab:"نزلت في عبد الله بن أم مكتوم ﵁ الأعمى، حين جاء للنبي ﷺ وهو منشغل بدعوة كبار قريش، فعبس النبي ﷺ وأعرض، فعاتبه الله برفق.",fadl:"",action:"لا تحتقر أحداً ولا تتجاهل ضعيفاً، فربما يكون الفقير أو المريض أقرب إلى الله من أهل المناصب."},"93_3":{title:"ما ودعك ربك وما قلى",sabab:"نزلت حين احتُبس الوحي عن النبي ﷺ فترة، فقال المشركون إن ربه ودّعه وقلاه، فنزلت هذه الآية تطمينًا للنبي ﷺ.",fadl:"",action:"في لحظات تأخر الفرج أو الشعور بالوحدة، تذكر أن الله ما ودّعك ولا تركك. هو معك دائمًا."},"94_5":{title:"فإن مع العسر يسراً",sabab:"نزلت تسليةً للنبي ﷺ وتذكيراً بأن مع كل شدة فرجاً.",fadl:"كرّرها الله مرتين في سورة واحدة، فالعسر واحد باللام المعرّفة، واليسر اثنان بالتنكير، أي يُسران مقابل عسر واحد.",action:"مع كل صعوبة تواجهها، اعلم أن معها يُسراً، وكلما اشتدّ الضيق، كلما اقترب الفرج."},"97_1":{title:"إنا أنزلناه في ليلة القدر",sabab:"ذُكر للنبي ﷺ رجل من بني إسرائيل لبس السلاح مجاهداً وعابداً ألف شهر، فاستقلّ المسلمون أعمارهم وأعمالهم، فأنزل الله هذه السورة عطاءً لهذه الأمة.",fadl:"العبادة فيها خير من عبادة 83 سنة متواصلة (ألف شهر).",action:"أعمارنا قصيرة، لكن الله عوّضنا بمواسم تتضاعف فيها الأجور. استغل رمضان ومواسم الطاعات بذكاء."},"105_1":{title:"ألم تر كيف فعل ربك بأصحاب الفيل",sabab:"نزلت تذكيراً لأهل مكة بنعمة الله عليهم حين حماهم من جيش أبرهة الحبشي الذي جاء لهدم الكعبة بفيل ضخم ليصرف الحجاج لكنيسته.",fadl:"",action:"مهما بلغت قوة أعدائك أو حجم التحديات في حياتك، تذكر أن الله قادر على إهلاكهم بأضعف جنوده (طير أبابيل)."},"106_1":{title:"لإيلاف قريش",sabab:"امتن الله على قريش برحلتي الشتاء والصيف للتجارة، وحمايتهم في الحرم، ليدعوهم لعبادته وحده شكراً على الأمن والرزق.",fadl:"",action:"الأمان في بيتك ووجود الطعام على مائدتك نعمتان عظيمتان. لا تعتد النعمة، بل اشكر مُنعمها دوماً."},"108_1":{title:"إنا أعطيناك الكوثر",sabab:"مات أبناء النبي ﷺ الذكور، فقال أحد المشركين: دعوه فإنه أبتر (مقطوع النسل والذكر)، فأنزل الله السورة دفاعاً عنه وتبشيراً له بنهر الكوثر.",fadl:"",action:"من يدافع عن الله ورسوله يرفع الله ذكره ويخلده، ومن يعاديهم يُبتر ذكره وتنمحي سيرته. كن دائماً في صف الحق."},"109_1":{title:"قل يا أيها الكافرون",sabab:"عرض كفار قريش على النبي ﷺ تسوية مضحكة: أن يعبد آلهتهم سنة، ويعبدون إلهه سنة! فنزلت السورة تقطع أي مساومة في العقيدة.",fadl:"تعدل ربع القرآن، وقراءتها قبل النوم براءة من الشرك.",action:"المبادئ لا تقبل المساومة ولا أنصاف الحلول. كن واضحاً وصريحاً في حقك ودينك ولا تتنازل إرضاءً للآخرين."},"111_1":{title:"تبت يدا أبي لهب وتب",sabab:"جمع النبي ﷺ قريشاً على جبل الصفا لدعوتهم، فقال له عمه أبو لهب: تباً لك سائر اليوم، ألهذا جمعتنا؟ فنزلت السورة رداً عليه وإبطالاً لكيده.",fadl:"",action:"القرابة والنسب لا تنفع بدون إيمان وعمل. أبو لهب عم النبي في النار، وبلال الحبشي في الجنة."},"112_1":{title:"قل هو الله أحد",sabab:"سأل المشركون أو اليهود النبي ﷺ عن صفة ربه وأصله ونسبه، فنزلت هذه السورة جواباً شاملاً وافياً.",fadl:"من قرأ قل هو الله أحد مرة واحدة كُتب له ثواب عشرة أعمال صالحة وتعدل ثلث القرآن.",action:"قرأتَ الآن آية تعدل ثلث القرآن. رددها بقلبك وتفكّر: الله الواحد الصمد هو خالقك ومعبودك."},"113_1":{title:"قل أعوذ برب الفلق",sabab:"سُحر النبي ﷺ من قِبَل يهودي يُدعى لبيد بن الأعصم، فأنزل الله المعوذتين رقيةً له، فكان كلما قرأ آية انحلت عقدة من السحر.",fadl:"قال النبي ﷺ: «ألم تر آيات أُنزلت الليلة لم يُرَ مثلهن قط؟ قل أعوذ برب الفلق وقل أعوذ برب الناس».",action:"حصن نفسك وأولادك يومياً بالمعوذتين، فهما أعظم وقاية من العين والحسد والسحر وشرور البشر."},"114_1":{title:"قل أعوذ برب الناس",sabab:"نزلت مع سورة الفلق حين سُحر النبي ﷺ ليسترقي بها ويتعوذ من شر شياطين الإنس والجن ووساوس الصدور.",fadl:"من المعوذتين اللتين لا يستعاذ بمثلهما قط في دفع كل شر.",action:"الشيطان يبدأ بالوسوسة الخفية في الصدر ليُحزنك أو يُفسد علاقتك بربك. اقطعه مباشرة بالتعوذ الصادق."}}};
